--
-- Name: add_merchant_topup_credits(uuid, integer, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_merchant_topup_credits(p_merchant_id uuid, p_credits integer, p_amount_gbp numeric, p_stripe_payment_intent_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing UUID;
BEGIN
  IF p_credits <= 0 THEN
    RAISE EXCEPTION 'p_credits must be positive';
  END IF;

  IF p_stripe_payment_intent_id IS NOT NULL THEN
    SELECT id INTO v_existing
    FROM credit_topup_log
    WHERE stripe_payment_intent_id = p_stripe_payment_intent_id
    LIMIT 1;

    IF FOUND THEN
      RETURN jsonb_build_object('ok', true, 'duplicate', true);
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('mc:' || p_merchant_id::text));

  SELECT p_merchant_id, 100, 0, date_trunc('month', now() AT TIME ZONE 'UTC') + interval '1 month'
  WHERE NOT EXISTS (SELECT 1 FROM merchant_credits WHERE merchant_id = p_merchant_id);

  UPDATE merchant_credits
  SET
    topup_credits_remaining = topup_credits_remaining + p_credits,
    updated_at = now()
  WHERE merchant_id = p_merchant_id;

  VALUES (p_merchant_id, p_credits, p_amount_gbp, p_stripe_payment_intent_id);

  RETURN jsonb_build_object('ok', true, 'duplicate', false);
END;
$$;


--
-- Name: all_processing_job_chunks_complete(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.all_processing_job_chunks_complete(p_job_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    AS $$
  SELECT NOT EXISTS (
    SELECT 1 FROM processing_job_chunks
    WHERE job_id = p_job_id AND status <> 'completed'
  )
  AND EXISTS (
    SELECT 1 FROM processing_job_chunks WHERE job_id = p_job_id
  );
$$;


--
-- Name: begin_processing_job_chunk(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_processing_job_chunk(p_job_id uuid, p_chunk_index integer) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_status text;
BEGIN
  SELECT status INTO v_status
  FROM processing_job_chunks
  WHERE job_id = p_job_id AND chunk_index = p_chunk_index
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN 'missing';
  END IF;

  IF v_status = 'completed' THEN
    RETURN 'completed';
  END IF;

  UPDATE processing_job_chunks
  SET status = 'processing', claimed_at = COALESCE(claimed_at, now())
  WHERE job_id = p_job_id AND chunk_index = p_chunk_index;

  RETURN 'processing';
END;
$$;


--
-- Name: bulk_upsert_co_occurrences(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_upsert_co_occurrences(p_pairs jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    entity_a_type,
    entity_a_value,
    entity_b_type,
    entity_b_value,
    co_occurrence_count,
    first_seen,
    last_seen
  )
  SELECT
    (p->>'a_type')::text,
    (p->>'a_value')::text,
    (p->>'b_type')::text,
    (p->>'b_value')::text,
    GREATEST(COALESCE((p->>'count_delta')::int, 1), 1),
    now(),
    now()
  FROM jsonb_array_elements(p_pairs) AS p
  WHERE
    (p->>'a_value') IS NOT NULL AND length(trim(p->>'a_value')) > 0
    AND (p->>'b_value') IS NOT NULL AND length(trim(p->>'b_value')) > 0
  ON CONFLICT (entity_a_type, entity_a_value, entity_b_type, entity_b_value)
  DO UPDATE SET
    co_occurrence_count = fraud_entity_co_occurrences.co_occurrence_count
                          + EXCLUDED.co_occurrence_count,
    last_seen = now();
END;
$$;


--
-- Name: bulk_upsert_fraud_entities(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_upsert_fraud_entities(p_entities jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    entity_type,
    entity_value,
    total_orders,
    total_refund_claims,
    total_chargebacks,
    flagged_count,
    match_score_avg,
    refund_timestamps,
    fastest_claim_days,
    first_seen,
    last_seen
  )
  SELECT
    (e->>'entity_type')::text,
    (e->>'entity_value')::text,
    COALESCE((e->>'orders_delta')::int, 0),
    COALESCE((e->>'refund_claims_delta')::int, 0),
    COALESCE((e->>'chargebacks_delta')::int, 0),
    COALESCE((e->>'flagged_delta')::int, 0),
    COALESCE((e->>'score_avg')::numeric, 0),
    CASE
      WHEN e->'refund_timestamps' IS NOT NULL AND e->'refund_timestamps' != 'null'::jsonb
      THEN e->'refund_timestamps'
      ELSE '[]'::jsonb
    END,
    CASE
      WHEN (e->>'fastest_claim_days') IS NOT NULL
      THEN (e->>'fastest_claim_days')::numeric
      ELSE NULL
    END,
    now(),
    now()
  FROM jsonb_array_elements(p_entities) AS e
  WHERE
    (e->>'entity_value') IS NOT NULL
    AND length(trim(e->>'entity_value')) > 0
  ON CONFLICT (entity_type, entity_value) DO UPDATE SET
    total_orders        = fraud_entities.total_orders        + EXCLUDED.total_orders,
    total_refund_claims = fraud_entities.total_refund_claims + EXCLUDED.total_refund_claims,
    total_chargebacks   = fraud_entities.total_chargebacks   + EXCLUDED.total_chargebacks,
    flagged_count       = fraud_entities.flagged_count       + EXCLUDED.flagged_count,
    match_score_avg     = (
      fraud_entities.match_score_avg * fraud_entities.total_orders
      + EXCLUDED.match_score_avg * EXCLUDED.total_orders
    ) / NULLIF(fraud_entities.total_orders + EXCLUDED.total_orders, 0),
    refund_timestamps   = (
      SELECT COALESCE(jsonb_agg(v ORDER BY ord), '[]'::jsonb)
      FROM (
        SELECT v, ord
        FROM (
          SELECT v, ord
          FROM jsonb_array_elements(COALESCE(fraud_entities.refund_timestamps, '[]'::jsonb)) WITH ORDINALITY t(v, ord)
          UNION ALL
          SELECT v, 1000000000 + ord
          FROM jsonb_array_elements(COALESCE(EXCLUDED.refund_timestamps, '[]'::jsonb)) WITH ORDINALITY t(v, ord)
        ) merged
        ORDER BY ord DESC
        LIMIT 120
      ) capped
    ),
    fastest_claim_days  = LEAST(
      COALESCE(fraud_entities.fastest_claim_days, 99999),
      COALESCE(EXCLUDED.fastest_claim_days, 99999)
    ),
    last_seen = now();
END;
$$;


--
-- Name: bulk_upsert_identifier_co_occurrence_edges(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_upsert_identifier_co_occurrence_edges(p_merchant_id uuid, p_edges jsonb, p_source_provider text DEFAULT 'unknown'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    merchant_id,
    left_identifier_type,
    left_identifier_hash,
    right_identifier_type,
    right_identifier_hash,
    source_provider,
    seen_count,
    link_strength,
    first_seen_at,
    last_seen_at
  )
  SELECT
    p_merchant_id,
    (p->>'left_type')::text,
    (p->>'left_hash')::text,
    (p->>'right_type')::text,
    (p->>'right_hash')::text,
    COALESCE(p_source_provider, 'unknown'),
    GREATEST(COALESCE((p->>'count_delta')::int, 1), 1),
    (1.0 + (GREATEST(COALESCE((p->>'count_delta')::int, 1), 1) - 1) * 0.5)::numeric(6, 2),
    now(),
    now()
  FROM jsonb_array_elements(p_edges) AS p
  WHERE
    p_merchant_id IS NOT NULL
    AND (p->>'left_type') IS NOT NULL
    AND length(trim(p->>'left_type')) > 0
    AND (p->>'left_hash') IS NOT NULL
    AND length(trim(p->>'left_hash')) > 0
    AND (p->>'right_type') IS NOT NULL
    AND length(trim(p->>'right_type')) > 0
    AND (p->>'right_hash') IS NOT NULL
    AND length(trim(p->>'right_hash')) > 0
    AND (p->>'left_type', p->>'left_hash')
        < (p->>'right_type', p->>'right_hash')
  ON CONFLICT (
    merchant_id,
    left_identifier_type,
    left_identifier_hash,
    right_identifier_type,
    right_identifier_hash
  ) DO UPDATE SET
    seen_count      = identifier_co_occurrence_edges.seen_count + EXCLUDED.seen_count,
    link_strength   = (
      1.0 + (identifier_co_occurrence_edges.seen_count + EXCLUDED.seen_count - 1) * 0.5
    )::numeric(6, 2),
    last_seen_at    = now(),
    source_provider = EXCLUDED.source_provider,
    updated_at      = now();
END;
$$;


