-- Name: bulk_upsert_identity_identifiers(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_upsert_identity_identifiers(p_identifiers jsonb, p_source_provider text DEFAULT 'unknown'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    identifier_type,
