--
-- Name: consume_context_credits_if_available(uuid, uuid, text, text, integer, timestamp with time zone, timestamp with time zone, integer, uuid, text, text, text, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_context_credits_if_available(p_merchant_id uuid, p_user_id uuid, p_plan_tier text, p_context_type text, p_credits_to_spend integer, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_monthly_allowance integer, p_claim_id uuid DEFAULT NULL::uuid, p_ticket_ref text DEFAULT NULL::text, p_order_ref text DEFAULT NULL::text, p_customer_ref text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_allow_soft_cap boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_monthly INTEGER;
  v_topup INTEGER;
  v_total INTEGER;
  v_soft_cap BOOLEAN;
  v_deduct JSONB;
  v_used INTEGER;
  v_allowance INTEGER;
BEGIN
  IF p_credits_to_spend < 0 THEN
    RAISE EXCEPTION 'p_credits_to_spend must be non-negative';
  END IF;

  IF p_monthly_allowance IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error_code', 'allowance_required',
      'used', 0,
      'remaining', 0,
      'credits_required', p_credits_to_spend
    );
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('mc:' || p_merchant_id::text));

  SELECT monthly_credits_remaining, topup_credits_remaining
    INTO v_monthly, v_topup
  FROM merchant_credits
  WHERE merchant_id = p_merchant_id
  FOR UPDATE;

  IF NOT FOUND THEN
    VALUES (p_merchant_id, p_monthly_allowance, 0, p_period_end)
    RETURNING monthly_credits_remaining, topup_credits_remaining INTO v_monthly, v_topup;
  END IF;

  v_total := v_monthly + v_topup;
  v_allowance := p_monthly_allowance;

  v_soft_cap := COALESCE(p_allow_soft_cap, FALSE)
    AND p_context_type = 'basic_context'
    AND p_credits_to_spend = 1
    AND v_total = 0;

  IF NOT v_soft_cap AND p_credits_to_spend > v_total THEN
    v_used := v_allowance - v_monthly;
    RETURN jsonb_build_object(
      'ok', false,
      'used', GREATEST(v_used, 0),
      'remaining', v_total,
      'credits_required', p_credits_to_spend
    );
  END IF;

  IF NOT v_soft_cap THEN
    v_deduct := deduct_merchant_credits(p_merchant_id, p_credits_to_spend);
    IF NOT (v_deduct->>'ok')::BOOLEAN THEN
      RETURN jsonb_build_object(
        'ok', false,
        'used', v_allowance - v_monthly,
        'remaining', v_total,
        'credits_required', p_credits_to_spend
      );
    END IF;
    SELECT monthly_credits_remaining, topup_credits_remaining
      INTO v_monthly, v_topup
    FROM merchant_credits
    WHERE merchant_id = p_merchant_id;
  END IF;

    merchant_id,
    user_id,
    plan_tier,
    context_type,
    credits_spent,
    claim_id,
    ticket_ref,
    order_ref,
    customer_ref,
    reason,
    metadata
  ) VALUES (
    p_merchant_id,
    p_user_id,
    p_plan_tier,
    p_context_type,
    CASE WHEN v_soft_cap THEN 0 ELSE p_credits_to_spend END,
    p_claim_id,
    p_ticket_ref,
    p_order_ref,
    p_customer_ref,
    p_reason,
    CASE
      WHEN v_soft_cap THEN COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('soft_cap_exhausted', true)
      ELSE COALESCE(p_metadata, '{}'::jsonb)
    END
  );

  v_used := v_allowance - v_monthly;

  RETURN jsonb_build_object(
    'ok', true,
    'used', GREATEST(v_used, 0),
    'remaining', v_monthly + v_topup,
    'monthly_remaining', v_monthly,
    'topup_remaining', v_topup,
    'credits_spent', CASE WHEN v_soft_cap THEN 0 ELSE p_credits_to_spend END,
    'soft_cap', v_soft_cap
  );
END;
$$;


