--
-- Name: identifier_co_occurrence_edges; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.identifier_co_occurrence_edges (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    merchant_id uuid NOT NULL,
    network_cluster_id uuid,
    left_identifier_type text NOT NULL,
    left_identifier_hash text NOT NULL,
    right_identifier_type text NOT NULL,
    right_identifier_hash text NOT NULL,
    source_event_id uuid,
    source_provider text DEFAULT 'unknown'::text NOT NULL,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    seen_count integer DEFAULT 1 NOT NULL,
    link_strength numeric(6,2) DEFAULT 1.00 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT identifier_co_occurrence_edges_canonical_order_check CHECK ((ROW(left_identifier_type, left_identifier_hash) < ROW(right_identifier_type, right_identifier_hash))),
    CONSTRAINT identifier_co_occurrence_edges_left_type_check CHECK ((left_identifier_type = ANY (ARRAY['normalized_email_hash'::text, 'phone_e164_hash'::text, 'full_normalized_shipping_address_hash'::text, 'full_normalized_billing_address_hash'::text, 'platform_customer_id'::text, 'helpdesk_customer_id'::text, 'platform_order_id'::text, 'helpdesk_ticket_id'::text]))),
    CONSTRAINT identifier_co_occurrence_edges_link_strength_check CHECK ((link_strength >= 1.00)),
    CONSTRAINT identifier_co_occurrence_edges_right_type_check CHECK ((right_identifier_type = ANY (ARRAY['normalized_email_hash'::text, 'phone_e164_hash'::text, 'full_normalized_shipping_address_hash'::text, 'full_normalized_billing_address_hash'::text, 'platform_customer_id'::text, 'helpdesk_customer_id'::text, 'platform_order_id'::text, 'helpdesk_ticket_id'::text]))),
    CONSTRAINT identifier_co_occurrence_edges_seen_count_check CHECK ((seen_count >= 1)),
    CONSTRAINT identifier_co_occurrence_edges_source_provider_check CHECK ((source_provider = ANY (ARRAY['shopify'::text, 'bigcommerce'::text, 'woocommerce'::text, 'gorgias'::text, 'csv'::text, 'manual'::text, 'unknown'::text])))
);


--
-- Name: TABLE identifier_co_occurrence_edges; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.identifier_co_occurrence_edges IS 'Merchant-scoped identifier co-occurrence graph. One row per merchant per edge tuple. is_cross_merchant is derived via v_identifier_edges_cross_merchant (Step 3). link_strength: initial 1.0, +0.5 per seen_count increment, no ceiling in v1. Network-level table — service_role access only.';


--
-- Name: COLUMN identifier_co_occurrence_edges.network_cluster_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.identifier_co_occurrence_edges.network_cluster_id IS 'v1: nullable scaffold, no write path yet.';


--
-- Name: COLUMN identifier_co_occurrence_edges.link_strength; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.identifier_co_occurrence_edges.link_strength IS 'Identity-link confidence weight (not a risk score). Rule: 1.0 on first observation; link_strength = 1.0 + (seen_count - 1) * 0.5 on upsert.';


