--
-- Name: v_identifier_edges_cross_merchant; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_identifier_edges_cross_merchant WITH (security_invoker='true') AS
 SELECT left_identifier_type,
    left_identifier_hash,
    right_identifier_type,
    right_identifier_hash,
    count(DISTINCT merchant_id) AS participating_merchant_count,
    (count(DISTINCT merchant_id) >= 2) AS is_cross_merchant
   FROM public.identifier_co_occurrence_edges
  GROUP BY left_identifier_type, left_identifier_hash, right_identifier_type, right_identifier_hash;


--
-- Name: VIEW v_identifier_edges_cross_merchant; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_identifier_edges_cross_merchant IS 'Network-level edge reach. is_cross_merchant derived when participating_merchant_count >= 2. k-anonymity / aggregation thresholds applied at service-role query layer, not in this view.';


