--
-- Name: v_time_to_claim_buckets; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_time_to_claim_buckets WITH (security_invoker='true') AS
 SELECT id AS order_claim_context_id,
    support_case_id,
    merchant_id,
    order_ref,
    COALESCE(time_to_claim_days, days_since_delivery_at_claim) AS time_to_claim_days,
        CASE
            WHEN (COALESCE(time_to_claim_days, days_since_delivery_at_claim) IS NULL) THEN 'unknown'::text
            WHEN (COALESCE(time_to_claim_days, days_since_delivery_at_claim) <= 0) THEN 'same_day'::text
            WHEN ((COALESCE(time_to_claim_days, days_since_delivery_at_claim) >= 1) AND (COALESCE(time_to_claim_days, days_since_delivery_at_claim) <= 2)) THEN '1_to_2_days'::text
            WHEN ((COALESCE(time_to_claim_days, days_since_delivery_at_claim) >= 3) AND (COALESCE(time_to_claim_days, days_since_delivery_at_claim) <= 7)) THEN '3_to_7_days'::text
            WHEN ((COALESCE(time_to_claim_days, days_since_delivery_at_claim) >= 8) AND (COALESCE(time_to_claim_days, days_since_delivery_at_claim) <= 14)) THEN '8_to_14_days'::text
            WHEN ((COALESCE(time_to_claim_days, days_since_delivery_at_claim) >= 15) AND (COALESCE(time_to_claim_days, days_since_delivery_at_claim) <= 30)) THEN '15_to_30_days'::text
            WHEN (COALESCE(time_to_claim_days, days_since_delivery_at_claim) > 30) THEN 'over_30_days'::text
            ELSE 'unknown'::text
        END AS time_to_claim_bucket,
    created_at
   FROM public.order_claim_context occ;


--
-- Name: VIEW v_time_to_claim_buckets; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.v_time_to_claim_buckets IS 'Derived time-to-claim buckets. Sources canonical order_claim_context.time_to_claim_days with days_since_delivery_at_claim as fallback for rows ingested before Step 4.';


