-- Name: TABLE watchlist_appearances; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.watchlist_appearances IS 'DEPRECATED (2026-06-03): Audit-run appearance rows for retired watchlist_entries. No new upserts from ingest; purge-expired-audits may still delete by audit_id.';


--
-- Name: watchlist_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.watchlist_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    merchant_id uuid NOT NULL,
    customer_profile_id uuid,
    email_hash text,
    display_name text,
    display_email text,
    added_at timestamp with time zone DEFAULT now(),
    last_seen_risk text,
    last_seen_at timestamp with time zone,
    removed_by_merchant boolean DEFAULT false NOT NULL
);


--
-- Name: TABLE watchlist_entries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.watchlist_entries IS 'DEPRECATED (2026-06-03): Merchant customer watchlists retired in favor of case-scoped claim review. Legacy rows retained; CSV pipeline no longer syncs appearances. Do not build new features on this table.';


--
-- Name: webhook_logs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webhook_logs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text NOT NULL,
    external_case_id text,
    merchant_id uuid,
    status text NOT NULL,
    http_status integer,
    is_claim boolean,
    claim_type text,
    error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT webhook_logs_status_check CHECK ((status = ANY (ARRAY['success'::text, 'validation_error'::text, 'error'::text])))
);


